  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 6, 'Rastrear algoritmos passo a passo', 'Execute uma instrução por vez. Registre entradas e variáveis, avalie cada condição com o estado atual e confira como cada repetição altera o estado e termina.', '## 1. Leia as instruções na ordem
Um algoritmo é executado passo a passo. Uma atribuição substitui o valor atual de uma variável: se total começa em 4 e recebe total+2, o novo total é 6. Use o valor atualizado nas instruções seguintes.

## 2. Registre o estado
Monte uma tabela com uma coluna por variável e uma linha após cada instrução importante. Anote entrada, condição avaliada, ramo escolhido e saída. Isso ajuda a localizar a primeira divergência entre o esperado e o executado.

## 3. Avalie condições e limites
Substitua cada variável pelo valor atual. “>” exclui igualdade; “>=” inclui. Em AND, todas as condições precisam ser verdadeiras; em OR, basta uma. Em estruturas aninhadas, só avalie a condição interna quando o fluxo alcançar esse ponto.

## 4. Acompanhe repetições
Teste a condição no momento indicado, registre a iteração, atualize as variáveis e volte ao teste. Para um laço “enquanto n<4”, a condição é verificada antes de cada volta. Verifique o que muda para o laço poder terminar. Se nenhuma variável ou condição de parada mudar, pode haver repetição infinita.

## 5. Depure com casos que revelem erros
Teste valores comuns, limites, lista vazia e entradas que ativem ramos diferentes. Um único teste aprovado não prova correção para todas as entradas. Procure tipos de dados, atualização de estado, inicialização e ordem das atribuições.

## Exemplo resolvido
Comece a=1 e b=0; repita duas vezes: c=a+b; depois a=b; depois b=c. Volta 1: c=1, a=0, b=1. Volta 2: c=1, a=1, b=1. O par final é (1,1). Registrar c antes das duas atualizações evita usar valores antigos por engano.',
    'Entrada lista=[2,4], total=0. Iteração 1: valor=2; total=0+2=2. Iteração 2: valor=4; total=2+4=6. Saída: 6. Se a tabela mostrar total=4 na segunda volta, localize qual valor anterior foi perdido.', array['Escreva o estado inicial antes de executar a primeira linha.', 'Atualize uma variável por vez e use o novo valor nas linhas seguintes.', 'Teste limites e caminhos diferentes, não apenas um exemplo comum.']::text[], 26, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-computing-trace-algorithm-state-and-branches","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Somar e comparar números naturais.","Reconhecer variável, condição e repetição em instruções simples."],"key_concepts":["estado e atribuição","sequência","condição e ramo","AND e OR","iteração e sentinela","terminação","teste de limite e depuração"],"progression":[{"stage":"DIAGNOSTIC","focus":"Rastrear atribuições, ordem e condições simples.","questionIds":["v5-computing-trace-algorithm-01","v5-computing-trace-algorithm-02","v5-computing-trace-algorithm-03","v5-computing-trace-algorithm-04"]},{"stage":"PRACTICE","focus":"Acompanhar acumuladores, laços, tipos, índices e atualização de estado.","questionIds":["v5-computing-trace-algorithm-05","v5-computing-trace-algorithm-06","v5-computing-trace-algorithm-07","v5-computing-trace-algorithm-08","v5-computing-trace-algorithm-09","v5-computing-trace-algorithm-10","v5-computing-trace-algorithm-11","v5-computing-trace-algorithm-12","v5-computing-trace-algorithm-13","v5-computing-trace-algorithm-14","v5-computing-trace-algorithm-15","v5-computing-trace-algorithm-16"]},{"stage":"TRANSFER","focus":"Combinar condições, limites, rastreio e cobertura de testes.","questionIds":["v5-computing-trace-algorithm-17","v5-computing-trace-algorithm-18","v5-computing-trace-algorithm-19","v5-computing-trace-algorithm-20","v5-computing-trace-algorithm-21","v5-computing-trace-algorithm-22"]},{"stage":"CONSOLIDATION","focus":"Analisar término e localizar a primeira divergência no estado.","questionIds":["v5-computing-trace-algorithm-23","v5-computing-trace-algorithm-24","v5-computing-trace-algorithm-25"]},{"stage":"REVIEW","focus":"Reaplicar a tabela de rastreio e avaliar limites dos testes.","questionIds":["v5-computing-trace-algorithm-26","v5-computing-trace-algorithm-27"]}],"micro_explanations":[{"trigger":"UPDATE_STATE_IN_ORDER","text":"Após uma atribuição, use o novo valor nas próximas instruções; a ordem altera o resultado."},{"trigger":"CONDITION_AT_BOUNDARY","text":"> não inclui igualdade; >= inclui. Teste exatamente o valor-limite."},{"trigger":"LOOP_TERMINATION","text":"Para terminar, alguma atualização precisa tornar a condição falsa ou atingir o sinal de parada."},{"trigger":"BOOLEAN_COMBINATION","text":"AND exige que todas as partes sejam verdadeiras; OR exige pelo menos uma."},{"trigger":"TYPE_BEFORE_OPERATION","text":"O símbolo + pode somar números ou concatenar textos; confira o tipo recebido."},{"trigger":"TEST_COVERAGE","text":"Um teste cobre apenas o caminho executado; teste também limites e ramos alternativos."}],"remediations":[{"id":"TRACE_VARIABLES","misconception":"Adivinhar a saída sem atualizar todas as variáveis.","prompt":"Crie uma linha para cada instrução: anote valores antes, instrução executada e valores depois. Localize a primeira linha em que sua previsão difere."},{"id":"BRANCH_BY_CURRENT_STATE","misconception":"Escolher um ramo sem avaliar a condição com o estado atual.","prompt":"Substitua cada variável pelo valor atual, marque verdadeiro ou falso e siga somente o ramo correspondente."},{"id":"LOOP_STATE_CHANGE","misconception":"Ignorar que a condição do laço precisa mudar.","prompt":"Registre a condição no início e no fim da volta. Aponte qual instrução altera a variável usada na condição; se nenhuma, explique por que pode não terminar."},{"id":"BOUNDARY_AND_TYPE","misconception":"Confundir limite inclusivo ou operação de texto com número.","prompt":"Teste o valor exatamente no limite e classifique cada entrada como texto ou número antes de aplicar a operação."},{"id":"TEST_ALTERNATE_PATH","misconception":"Generalizar a partir de um único teste.","prompt":"Escolha entradas que façam a condição ser verdadeira, falsa e ficar no limite; registre o caminho de cada uma."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"publisher":"Ministério da Educação, Brasil","title":"Base Nacional Comum Curricular","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","license":"Referência curricular geral; alinhamento oficial específico não reivindicado."}],"copyright_note":"Algoritmos, entradas, tabelas de rastreio e explicações são autorais e usam dados hipotéticos. Revisão pedagógica pendente; sem mapeamento oficial reivindicado.","source_question_feedback":[{"questionId":"v3-computing-computing_algorithms-1","hint":"Acompanhe as instruções na ordem, registre o valor de cada variável após uma atribuição e teste a condição com os dados atuais antes de escolher o próximo ramo.","errorFocus":"STATE_TRANSITION_BRANCH_AND_TERMINATION"},{"questionId":"v3-computing-computing_algorithms-2","hint":"Acompanhe as instruções na ordem, registre o valor de cada variável após uma atribuição e teste a condição com os dados atuais antes de escolher o próximo ramo.","errorFocus":"STATE_TRANSITION_BRANCH_AND_TERMINATION"},{"questionId":"v3-computing-computing_algorithms-3","hint":"Acompanhe as instruções na ordem, registre o valor de cada variável após uma atribuição e teste a condição com os dados atuais antes de escolher o próximo ramo.","errorFocus":"STATE_TRANSITION_BRANCH_AND_TERMINATION"},{"questionId":"v3-computing-computing_algorithms-4","hint":"Acompanhe as instruções na ordem, registre o valor de cada variável após uma atribuição e teste a condição com os dados atuais antes de escolher o próximo ramo.","errorFocus":"STATE_TRANSITION_BRANCH_AND_TERMINATION"},{"questionId":"v3-computing-computing_algorithms-5","hint":"Acompanhe as instruções na ordem, registre o valor de cada variável após uma atribuição e teste a condição com os dados atuais antes de escolher o próximo ramo.","errorFocus":"STATE_TRANSITION_BRANCH_AND_TERMINATION"},{"questionId":"v3-computing-computing_algorithms-6","hint":"Acompanhe as instruções na ordem, registre o valor de cada variável após uma atribuição e teste a condição com os dados atuais antes de escolher o próximo ramo.","errorFocus":"STATE_TRANSITION_BRANCH_AND_TERMINATION"},{"questionId":"v3-computing-computing_algorithms-7","hint":"Acompanhe as instruções na ordem, registre o valor de cada variável após uma atribuição e teste a condição com os dados atuais antes de escolher o próximo ramo.","errorFocus":"STATE_TRANSITION_BRANCH_AND_TERMINATION"},{"questionId":"v3-computing-computing_algorithms-11","hint":"Acompanhe as instruções na ordem, registre o valor de cada variável após uma atribuição e teste a condição com os dados atuais antes de escolher o próximo ramo.","errorFocus":"STATE_TRANSITION_BRANCH_AND_TERMINATION"},{"questionId":"v4-authored-computing-review-01","hint":"Acompanhe as instruções na ordem, registre o valor de cada variável após uma atribuição e teste a condição com os dados atuais antes de escolher o próximo ramo.","errorFocus":"STATE_TRANSITION_BRANCH_AND_TERMINATION"}],"objective":"Acompanhar estado de variáveis, condições, repetições e caminhos de execução para prever resultados e localizar erros.","common_mistake":"Adivinhar a saída sem acompanhar as atribuições, testar uma condição com um valor desatualizado, ou esquecer que o laço precisa alterar o estado para terminar.","estimated_minutes":26}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
