  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-computing-trace-algorithm-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"TRACE","contextFamily":"ASSIGNMENT_ORDER","statement":"Rastreie: iniciar pontos em 2; somar 3; mostrar pontos. Qual valor é exibido?","options":["5.","2, porque a soma vem depois da exibição.","23, porque os valores sempre são unidos como texto.","3, porque o valor inicial é descartado."],"correctAnswer":"5.","explanation":"A variável começa em 2 e recebe mais 3 antes da exibição: 2 + 3 = 5.","hint":"Acompanhe o valor inicial e aplique as instruções na ordem.","errorFocus":"STEP_ORDER_IGNORED","misconceptions":{"2, porque a soma vem depois da exibição.":["STEP_ORDER_IGNORED"]},"position":1},{"id":"v5-computing-trace-algorithm-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"CONDITION_TRUE","statement":"Um algoritmo diz: “se a temperatura for menor que 18, mostrar aviso”. Para entrada 15, qual caminho ocorre?","options":["Não mostrar, pois 15 é maior que 18.","Mostrar o aviso, pois 15 é menor que 18.","Mostrar sempre, qualquer que seja a entrada.","Parar antes de verificar a condição."],"correctAnswer":"Mostrar o aviso, pois 15 é menor que 18.","explanation":"A condição 15 < 18 é verdadeira, então o algoritmo executa o aviso.","hint":"Substitua a variável pelo valor e avalie a comparação.","errorFocus":"CONDITION_NOT_EVALUATED","misconceptions":{"Não mostrar, pois 15 é maior que 18.":["CONDITION_NOT_EVALUATED"]},"position":2},{"id":"v5-computing-trace-algorithm-03","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"TRACE","contextFamily":"COUNTED_LOOP","statement":"Uma repetição executa a ação uma vez para cada item de uma lista com quatro itens. Quantas vezes a ação ocorre?","options":["Três vezes, porque a lista tem quatro posições.","Uma vez, porque há apenas uma repetição.","Quatro vezes.","Cinco vezes, contando o início e o fim como itens."],"correctAnswer":"Quatro vezes.","explanation":"A ação ocorre uma vez para cada um dos quatro itens.","hint":"Conte os itens processados, não as linhas de código.","errorFocus":"LOOP_COUNT_OFF_BY_ONE","misconceptions":{"Três vezes, porque a lista tem quatro posições.":["LOOP_COUNT_OFF_BY_ONE"]},"position":3},{"id":"v5-computing-trace-algorithm-04","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"IF_ELSE_BRANCH","statement":"Em “se nota >= 6, aprovar; caso contrário, revisar”, qual ação ocorre quando nota vale 5?","options":["Aprovar, pois qualquer nota numérica atende à condição.","Executar as duas ações sempre.","Nenhuma ação, pois 5 não é um texto.","Revisar."],"correctAnswer":"Revisar.","explanation":"5 >= 6 é falso, então o caminho “caso contrário” é executado.","hint":"Avalie a condição antes de escolher o ramo.","errorFocus":"FALSE_BRANCH_SKIPPED","misconceptions":{"Aprovar, pois qualquer nota numérica atende à condição.":["FALSE_BRANCH_SKIPPED"]},"position":4},{"id":"v5-computing-trace-algorithm-05","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"TRACE","contextFamily":"COUNTER_UPDATE","statement":"Rastreie contador=0; repetir duas vezes: contador=contador+1. Qual valor final?","options":["2.","1, porque a variável começa em zero.","3, porque se conta a condição final como atualização.","0, porque a repetição não altera variáveis."],"correctAnswer":"2.","explanation":"Cada uma das duas iterações soma 1: 0 → 1 → 2.","hint":"Anote o valor após cada repetição.","errorFocus":"COUNTER_UPDATE_MISCOUNTED","misconceptions":{"1, porque a variável começa em zero.":["COUNTER_UPDATE_MISCOUNTED"]},"position":1},{"id":"v5-computing-trace-algorithm-06","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"TRACE","contextFamily":"CONDITIONAL_BOUNDARY","statement":"O algoritmo executa “se idade >= 13, permitir”. Qual entrada é a menor que permite o acesso?","options":["12, porque está perto de 13.","13.","14, porque >= significa maior que, sem incluir igualdade.","0, porque a condição não limita o valor."],"correctAnswer":"13.","explanation":"A expressão >= inclui a igualdade; 13 atende à condição.","hint":"Confira se o símbolo inclui ou exclui o limite.","errorFocus":"INCLUSIVE_BOUNDARY_READ_AS_EXCLUSIVE","misconceptions":{"12, porque está perto de 13.":["INCLUSIVE_BOUNDARY_READ_AS_EXCLUSIVE"]},"position":2},{"id":"v5-computing-trace-algorithm-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"ACCUMULATOR","statement":"Comece total=0. Para cada valor em 2, 4 e 1, some o valor ao total. Qual sequência de totais aparece após cada item?","options":["2, 4, 1.","0, 2, 4.","2, 6, 7.","7, 5, 1."],"correctAnswer":"2, 6, 7.","explanation":"O acumulador recebe os valores em ordem: 0+2=2, 2+4=6, 6+1=7.","hint":"Atualize o total depois de cada item e mantenha o resultado anterior.","errorFocus":"ACCUMULATOR_REPLACED_OR_RESET","misconceptions":{"2, 4, 1.":["ACCUMULATOR_REPLACED_OR_RESET"]},"position":3},{"id":"v5-computing-trace-algorithm-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"WHILE_LOOP","statement":"Rastreie: n=1; enquanto n<4, mostrar n e somar 1 a n. Quais valores são mostrados?","options":["1, 2, 3 e 4.","2, 3 e 4.","Apenas 1, pois n muda depois da condição.","1, 2 e 3."],"correctAnswer":"1, 2 e 3.","explanation":"A condição é testada antes de cada execução. Quando n chega a 4, n<4 é falso e a repetição termina.","hint":"Teste a condição antes de entrar em cada volta.","errorFocus":"WHILE_BOUNDARY_OR_ORDER","misconceptions":{"1, 2, 3 e 4.":["WHILE_BOUNDARY_OR_ORDER"]},"position":4},{"id":"v5-computing-trace-algorithm-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"SENTINEL_INPUT","statement":"O algoritmo lê valores até receber 0, que serve como sinal de parada e não deve ser somado. Entradas: 5, 2, 0. Qual total?","options":["7.","7, porque 0 também é um valor normal da lista.","5, porque só a primeira entrada é lida.","0, porque o sinal de parada substitui o total."],"correctAnswer":"7.","explanation":"Somam-se 5 e 2; o 0 encerra a leitura e, conforme a regra, não entra no total.","hint":"Identifique primeiro se o valor sentinela é dado ou comando de parada.","errorFocus":"SENTINEL_INCLUDED_IN_DATA","misconceptions":{"7, porque 0 também é um valor normal da lista.":["SENTINEL_INCLUDED_IN_DATA"]},"position":5},{"id":"v5-computing-trace-algorithm-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"BOOLEAN_AND","statement":"Uma ação ocorre se “tem autorização” e “horário permitido” forem verdadeiros. Autorização=true e horário=false. A ação ocorre?","options":["Sim; uma condição verdadeira basta sempre.","Não; com AND, as duas condições precisam ser verdadeiras.","Sim; a segunda condição é ignorada.","Não é possível decidir sem somar os valores."],"correctAnswer":"Não; com AND, as duas condições precisam ser verdadeiras.","explanation":"A conjunção AND só é verdadeira quando ambas as condições são verdadeiras.","hint":"Avalie cada condição separadamente e depois combine pelo operador.","errorFocus":"AND_READ_AS_OR","misconceptions":{"Sim; uma condição verdadeira basta sempre.":["AND_READ_AS_OR"]},"position":6},{"id":"v5-computing-trace-algorithm-11","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DEBUG","contextFamily":"TYPE_CONVERSION","statement":"Um programa recebe os textos “2” e “3”. Ao usar “+”, exibe “23”. O que explica esse resultado e como corrigir se o objetivo é somar?","options":["A soma numérica de 2 e 3 é 23.","A tela inverteu os algarismos; trocar a cor corrige.","Os valores foram tratados como texto; converter ambos para números antes da soma.","O programa deve repetir a concatenação até virar número."],"correctAnswer":"Os valores foram tratados como texto; converter ambos para números antes da soma.","explanation":"A concatenação de textos produz “23”. Converter os valores para números permite obter 5.","hint":"Verifique o tipo dos dados antes da operação.","errorFocus":"TEXT_CONCATENATION_AS_ADDITION","misconceptions":{"A soma numérica de 2 e 3 é 23.":["TEXT_CONCATENATION_AS_ADDITION"]},"position":7},{"id":"v5-computing-trace-algorithm-12","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"NESTED_CONDITION","statement":"Primeiro, se saldo>=10, o programa verifica se ativo=true e então libera. Saldo=12 e ativo=false. Qual resultado?","options":["Liberar, porque basta a condição externa.","Não liberar, porque saldo 12 é menor que 10.","Executar o ramo de saldo insuficiente.","Não liberar; o saldo passa na primeira condição, mas a segunda falha."],"correctAnswer":"Não liberar; o saldo passa na primeira condição, mas a segunda falha.","explanation":"A condição externa é verdadeira, então a interna é testada. Como ativo é falso, a liberação não ocorre.","hint":"Siga a entrada na ordem e avalie cada condição alcançada.","errorFocus":"INNER_CONDITION_SKIPPED","misconceptions":{"Liberar, porque basta a condição externa.":["INNER_CONDITION_SKIPPED"]},"position":8},{"id":"v5-computing-trace-algorithm-13","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DEBUG","contextFamily":"LOOP_VARIABLE_UPDATE","statement":"Um laço continua enquanto contador<3, mas dentro dele o contador nunca muda. Qual problema é provável?","options":["A condição pode continuar verdadeira e o laço não terminar.","O contador sempre chegará a 3 sozinho.","O laço executará exatamente três vezes.","A condição deixa de ser verificada após a primeira volta."],"correctAnswer":"A condição pode continuar verdadeira e o laço não terminar.","explanation":"Sem atualizar contador, a condição pode permanecer verdadeira indefinidamente. Um passo de atualização ou outra condição de parada é necessário.","hint":"Procure qual instrução pode tornar a condição falsa.","errorFocus":"LOOP_STATE_NEVER_CHANGES","misconceptions":{"O contador sempre chegará a 3 sozinho.":["LOOP_STATE_NEVER_CHANGES"]},"position":9},{"id":"v5-computing-trace-algorithm-14","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"MAXIMUM_TRACKING","statement":"Percorra os valores 6, 2, 9. max começa em 6 e é atualizado quando um valor é maior. Qual valor final?","options":["6, porque max nunca pode mudar.","9.","2, porque é o último valor menor.","17, porque os valores são somados."],"correctAnswer":"9.","explanation":"6 permanece após comparar 2; 9 é maior que 6 e passa a ser o máximo.","hint":"Compare cada novo valor ao máximo guardado até aquele momento.","errorFocus":"MAXIMUM_NOT_UPDATED","misconceptions":{"6, porque max nunca pode mudar.":["MAXIMUM_NOT_UPDATED"]},"position":10},{"id":"v5-computing-trace-algorithm-15","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"INDEX_AND_ITEM","statement":"Uma lista é [“sol”, “lua”, “mar”] e a posição começa em 0. Qual item está na posição 1?","options":["“sol”, porque a primeira posição é 1.","“mar”, porque a contagem começa no fim.","“lua”.","Não existe posição 1 em uma lista de três itens."],"correctAnswer":"“lua”.","explanation":"Com posições iniciadas em 0, sol está em 0, lua em 1 e mar em 2.","hint":"Escreva o índice abaixo de cada item antes de selecionar.","errorFocus":"ZERO_BASED_INDEX_CONFUSION","misconceptions":{"“sol”, porque a primeira posição é 1.":["ZERO_BASED_INDEX_CONFUSION"]},"position":11},{"id":"v5-computing-trace-algorithm-16","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"LOOP_WITH_SKIP","statement":"Para cada número de 1 a 5, o algoritmo pula os pares e mostra os demais. O que é exibido?","options":["2 e 4.","1, 2, 3, 4 e 5.","5, 4, 3, 2 e 1.","1, 3 e 5."],"correctAnswer":"1, 3 e 5.","explanation":"Os valores pares 2 e 4 são pulados; os ímpares restantes são mostrados na ordem.","hint":"Teste a condição de paridade em cada valor antes de mostrar.","errorFocus":"SKIP_CONDITION_INVERTED","misconceptions":{"2 e 4.":["SKIP_CONDITION_INVERTED"]},"position":12},{"id":"v5-computing-trace-algorithm-17","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"INPUT_SEQUENCE","statement":"Um programa começa tentativas=0. Para cada entrada, soma 1 se a resposta estiver incorreta; entradas: correta, incorreta, incorreta. Qual resultado final?","options":["2 tentativas incorretas.","3, pois todas as respostas contam como erro.","1, pois o contador só aumenta uma vez.","0, porque respostas corretas anulam erros."],"correctAnswer":"2 tentativas incorretas.","explanation":"O contador aumenta apenas nas duas entradas incorretas: 0 → 1 → 2.","hint":"Rastreie o ramo executado em cada entrada, não só o número de entradas.","errorFocus":"COUNTS_ALL_INPUTS_OR_UNDERCOUNTS","misconceptions":{"3, pois todas as respostas contam como erro.":["COUNTS_ALL_INPUTS_OR_UNDERCOUNTS"]},"position":1},{"id":"v5-computing-trace-algorithm-18","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"TRACE","contextFamily":"COMBINED_CONDITION","statement":"Um sistema permite retirada quando quantidade>0 e cadastro ativo. Quantidade=1 e cadastro ativo=true. A retirada é permitida?","options":["Não; quantidade precisa ser maior que 1.","Sim; as duas condições são verdadeiras.","Não; AND exige que uma das condições seja falsa.","Sim, mesmo se cadastro estivesse inativo."],"correctAnswer":"Sim; as duas condições são verdadeiras.","explanation":"1>0 e ativo=true; ambas as condições se cumprem, então a ação é permitida.","hint":"Avalie cada parte da condição composta com os valores dados.","errorFocus":"COMPOUND_CONDITION_PARTIAL_EVALUATION","misconceptions":{"Não; quantidade precisa ser maior que 1.":["COMPOUND_CONDITION_PARTIAL_EVALUATION"]},"position":2},{"id":"v5-computing-trace-algorithm-19","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"DEBUG","contextFamily":"TEST_BOUNDARIES","statement":"Um desconto é aplicado se total>100. Em outro exemplo, a regra escrita é total>=100. O que muda quando total vale exatamente 100?","options":["As duas são falsas, porque 100 não é maior que 100.","As duas são verdadeiras, pois usam o mesmo limite.","A primeira condição é falsa e a segunda é verdadeira.","A primeira é verdadeira e a segunda é falsa."],"correctAnswer":"A primeira condição é falsa e a segunda é verdadeira.","explanation":"O operador > exclui a igualdade; >= a inclui. O valor de fronteira revela a diferença.","hint":"Substitua exatamente 100 e avalie cada operador, sem arredondar.","errorFocus":"BOUNDARY_OPERATOR_CONFUSED","misconceptions":{"As duas são falsas, porque 100 não é maior que 100.":["BOUNDARY_OPERATOR_CONFUSED"]},"position":3},{"id":"v5-computing-trace-algorithm-20","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"TRACE","contextFamily":"TRACE_TABLE","statement":"Um algoritmo começa a=1 e b=0. Em cada volta, calcula c=a+b, depois a=b e b=c; executa duas voltas. Qual é o par (a,b) final?","options":["(2, 1).","(1, 2).","(3, 2).","(1, 1)."],"correctAnswer":"(1, 1).","explanation":"Volta 1: c=1, a=0, b=1. Volta 2: c=1, a=1, b=1. Portanto, o par final é (1,1).","hint":"Recalcule as atribuições usando os valores anteriores; registre c antes de alterar a e b.","errorFocus":"VARIABLE_UPDATE_ORDER","misconceptions":{"(2, 1).":["VARIABLE_UPDATE_ORDER"]},"position":4},{"id":"v5-computing-trace-algorithm-21","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"TEST_CASE_COVERAGE","statement":"Um algoritmo tem ramo para lista vazia e ramo para lista com itens. Qual conjunto mínimo de testes cobre os dois ramos?","options":["Testar uma lista vazia e uma lista com pelo menos um item.","Testar duas listas vazias.","Testar apenas uma lista longa.","Testar uma lista com itens repetidos, sem testar a lista vazia."],"correctAnswer":"Testar uma lista vazia e uma lista com pelo menos um item.","explanation":"Os testes precisam ativar cada condição: ausência de itens e presença de ao menos um item.","hint":"Escolha entradas que façam cada ramo ser executado.","errorFocus":"TESTS_DO_NOT_COVER_BRANCHES","misconceptions":{"Testar duas listas vazias.":["TESTS_DO_NOT_COVER_BRANCHES"]},"position":5},{"id":"v5-computing-trace-algorithm-22","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"DEBUG","contextFamily":"ORDER_OF_ASSIGNMENTS","statement":"Comece x=4 e y=1. Execute: x=x+y; y=x-y. Quais valores finais?","options":["x=5 e y=1.","x=5 e y=4.","x=4 e y=5.","x=3 e y=1."],"correctAnswer":"x=5 e y=4.","explanation":"Primeiro x vira 5; depois y recebe 5-1=4. A segunda linha usa o novo valor de x.","hint":"Atualize a variável imediatamente após cada instrução.","errorFocus":"OLD_VALUE_USED_AFTER_ASSIGNMENT","misconceptions":{"x=5 e y=1.":["OLD_VALUE_USED_AFTER_ASSIGNMENT"]},"position":6},{"id":"v5-computing-trace-algorithm-23","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"LOOP_TERMINATION","statement":"Uma lista contém três itens e o algoritmo remove um item processado a cada volta enquanto a lista não estiver vazia. Quando termina?","options":["Antes de processar o primeiro item.","Após remover apenas um, porque há uma condição.","Depois de processar e remover os três itens, quando a lista fica vazia.","Nunca, mesmo que a lista fique vazia."],"correctAnswer":"Depois de processar e remover os três itens, quando a lista fica vazia.","explanation":"A condição é verificada novamente após cada remoção; com os três itens processados, a lista fica vazia e o laço para.","hint":"Acompanhe a lista e a condição no início de cada volta.","errorFocus":"TERMINATION_CONDITION_IGNORED","misconceptions":{"Antes de processar o primeiro item.":["TERMINATION_CONDITION_IGNORED"]},"position":1},{"id":"v5-computing-trace-algorithm-24","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"TRACE","contextFamily":"MINIMUM_INITIALIZATION","statement":"Para encontrar o menor de uma lista não vazia, min começa no primeiro valor. Por que isso é mais seguro que começar min=0 quando todos os valores são positivos?","options":["Porque min precisa sempre ser negativo.","Porque a lista não pode conter números positivos.","Porque começar pelo primeiro valor elimina todas as comparações.","Porque 0 poderia continuar menor que todos os valores e não pertencer à lista."],"correctAnswer":"Porque 0 poderia continuar menor que todos os valores e não pertencer à lista.","explanation":"Inicializar com um valor real da lista garante que o candidato a mínimo possa ser um dos dados. Depois, compara-se cada valor restante.","hint":"Teste a inicialização com a lista 3, 8 e 5.","errorFocus":"INVALID_SENTINEL_FOR_EXTREME","misconceptions":{"Porque min precisa sempre ser negativo.":["INVALID_SENTINEL_FOR_EXTREME"]},"position":2},{"id":"v5-computing-trace-algorithm-25","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"DEBUG","contextFamily":"TRACE_AND_ASSERT","statement":"Uma tabela de rastreio mostra que uma variável deveria aumentar em cada volta, mas permanece igual. Qual é o próximo passo útil?","options":["Verificar a instrução de atualização e a condição do laço usando os valores daquela volta.","Mudar a saída esperada até coincidir com a tabela.","Apagar a variável e manter o laço.","Concluir que todo algoritmo repetitivo é imprevisível."],"correctAnswer":"Verificar a instrução de atualização e a condição do laço usando os valores daquela volta.","explanation":"Comparar a transição esperada com a observada ajuda a localizar uma atribuição ausente ou condição que não muda.","hint":"Encontre a primeira linha em que o estado esperado e o registrado divergem.","errorFocus":"TRACE_DIVERGENCE_NOT_INVESTIGATED","misconceptions":{"Mudar a saída esperada até coincidir com a tabela.":["TRACE_DIVERGENCE_NOT_INVESTIGATED"]},"position":3},{"id":"v5-computing-trace-algorithm-26","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"SEQUENCE","contextFamily":"TRACE_METHOD","statement":"Qual método é mais confiável para rastrear um algoritmo com condição e repetição?","options":["Ler apenas a última linha e adivinhar a saída.","Registrar entradas e variáveis após cada instrução, testar a condição na ordem e anotar cada iteração.","Pular condições que parecem óbvias.","Alterar valores durante o rastreio para facilitar a conta."],"correctAnswer":"Registrar entradas e variáveis após cada instrução, testar a condição na ordem e anotar cada iteração.","explanation":"A tabela de rastreio acompanha o estado e os ramos realmente executados, permitindo conferir a saída passo a passo.","hint":"Mantenha um registro de estado após cada atribuição e decisão.","errorFocus":"STATE_NOT_RECORDED","misconceptions":{"Ler apenas a última linha e adivinhar a saída.":["STATE_NOT_RECORDED"]},"position":1},{"id":"v5-computing-trace-algorithm-27","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"ALGORITHM_LIMITS","statement":"Um algoritmo foi testado com uma entrada e funcionou. Qual conclusão é adequada?","options":["Ele está correto para toda entrada possível.","O teste não fornece nenhuma informação.","Ele funcionou para aquele caso; outros casos, limites e entradas inesperadas ainda precisam de teste.","Não é necessário verificar as condições ou os limites."],"correctAnswer":"Ele funcionou para aquele caso; outros casos, limites e entradas inesperadas ainda precisam de teste.","explanation":"Um caso aprovado é evidência limitada. Testes adicionais devem cobrir ramos, limites e entradas relevantes.","hint":"Mantenha a conclusão dentro das entradas realmente verificadas.","errorFocus":"ONE_TEST_GENERALIZED","misconceptions":{"Ele está correto para toda entrada possível.":["ONE_TEST_GENERALIZED"]},"position":2}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 6, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-computing-trace-algorithm-state-and-branches',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 6
       and metadata->>'content_id' = 'v5-computing-trace-algorithm-state-and-branches' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'COMPUTING', 'ALGORITMOS', 'rastreio_condicoes_repeticoes_e_debug',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

